  if(!Number.isInteger(delay)||delay<0||delay>60)throw Error('Popup delay must be between 0 and 60 seconds.');
  if(!Number.isInteger(frequency)||frequency<1||frequency>10080)throw Error('Repeat interval must be between 1 and 10080 minutes.');
  const ctaUrl=$('promoCtaUrl').value.trim();
  if(ctaUrl&&!/^(https:\/\/|mailto:|tel:|\/|#)/i.test(ctaUrl))throw Error('CTA destination must use HTTPS, mailto:, tel:, or a site path.');
  if(ctaUrl.startsWith('//'))throw Error('Protocol-relative CTA URLs are not allowed.');
  const promo={enabled:$('promoEnabled').checked,delaySeconds:delay,frequencyMinutes:frequency,animation:$('promoAnimation').value,title:$('promoTitle').value.trim(),headline:$('promoHeadline').value.trim(),intro:$('promoIntro').value.trim(),stepsTitle:$('promoStepsTitle').value.trim(),steps,benefitsTitle:$('promoBenefitsTitle').value.trim(),benefits,closing:$('promoClosing').value.trim(),ctaText:$('promoCtaText').value.trim(),ctaUrl,ctaEffect:$('promoCtaEffect').value};
